// App members: private media never enters the generated-image gallery.
std::thread accountMediaThread;std::atomic_bool accountMediaCancel=false,accountMediaActive=false;
bool accountMediaBusy=false,accountMediaLoaded=false;uint64_t accountMediaSerial=0;
std::string accountMediaScope,accountMediaOwner;json accountMediaRows=json::object(),accountMediaRetry=json::object();
