void resetAccountMedia(){accountMediaCancel=true;++accountMediaSerial;accountMediaBusy=false;accountMediaLoaded=false;accountMediaRows=json::object();accountMediaRetry=json::object();accountMediaScope.clear();accountMediaOwner.clear();accountMediaMessage.clear();accountMediaImages.reset();for(auto& bitmap:accountMediaBitmaps)bitmap.Reset();}
bool accountMediaSupported(){return flag(accountProfile,"profile_media_supported");}
void startAccountMedia(json operation=json::object()){
 if(!accountMediaSupported()||accountMediaBusy||accountMediaActive||accountTransition||accountSaving||accountSaveWorkerActive)return;
 bindAccountDraft();bool writing=!operation.empty();if(writing&&(accountDraftDirty||accountDraftBlocked)){accountMediaMessage=L"닉네임·소개를 저장한 뒤 다시 시도하세요";return;}
 auto owner=str(accountProfile,"account_id"),scope=store->workspaceScope;if(owner.empty()||scope.empty())return;
 if(accountMediaThread.joinable())accountMediaThread.join();auto cfg=store->settings;auto expected=accountDraftVersion;if(writing&&expected.size()!=64)return;
 auto folder=store->root/"cache/account-media";auto serial=++accountMediaSerial;accountMediaScope=scope;accountMediaOwner=owner;accountMediaCancel=false;accountMediaActive=true;accountMediaBusy=true;accountMediaMessage=writing?L"사진 저장 중…":L"사진 불러오는 중…";if(writing)accountMediaRetry=operation;auto* target=engine;
 try{accountMediaThread=std::thread([this,cfg,owner,scope,expected,folder,serial,operation,writing,target]{CoInitializeEx(nullptr,COINIT_MULTITHREADED);json result={{"owner",owner},{"scope",scope},{"serial",serial},{"expected",expected},{"writing",writing}};
 try{NetworkScope network(&accountMediaCancel,std::chrono::steady_clock::now()+std::chrono::seconds(35),"standard");AccountOwnerScope bound(owner);auto base=str(cfg,"api"),key=str(cfg,"api_key");
 if(writing){auto kind=str(operation,"kind"),action=str(operation,"action");if(kind!="avatar"&&kind!="banner")throw std::runtime_error("사진 종류를 확인하세요.");Response reply;
 if(action=="upload"){Multipart form;form.field("expected_version",expected);form.field("request_id",str(operation,"token"));form.file("image",fs::path(wide(str(operation,"file"))),5*1024*1024);reply=request("POST",joinUrl(base,"/api/profile-media/"+kind),key,form.finish(),form.type(),&accountMediaCancel,65536,35000);}
 else{if(action!="clear"&&action!="undo")throw std::runtime_error("사진 작업을 확인하세요.");reply=request(action=="clear"?"DELETE":"POST",joinUrl(base,"/api/profile-media/"+kind+(action=="undo"?"/undo":"")),key,json{{"expected_version",expected}}.dump(),"application/json",&accountMediaCancel,65536,35000);}
 auto ack=reply.object();if(str(ack,"account_id")!=owner)throw std::runtime_error("사진 응답을 확인할 수 없습니다.");auto version=str(ack,"profile_version");if(version.size()!=64||version.find_first_not_of("0123456789abcdef")!=std::string::npos)throw std::runtime_error("사진 응답을 확인할 수 없습니다.");result["applied_version"]=version;}
 auto metadata=request("GET",joinUrl(base,"/api/profile-media"),key,"","application/json",&accountMediaCancel,65536,35000).object();if(str(metadata,"account_id")!=owner||!metadata.contains("media")||!metadata["media"].is_object())throw std::runtime_error("사진 응답을 확인할 수 없습니다.");result["metadata"]=metadata;result["files"]=json::object();
 for(auto kind:{"avatar","banner"}){auto row=metadata["media"].value(kind,json::object());if(!row.is_object()||!row.contains("current")||row["current"].is_null())continue;auto current=row["current"];auto hash=str(current,"sha256");if(hash.size()!=64||hash.find_first_not_of("0123456789abcdef")!=std::string::npos)throw std::runtime_error("사진 응답을 확인할 수 없습니다.");auto path=folder/(std::string(kind)+"-"+hash+".jpg");std::string pixels;
 if(fs::is_regular_file(path)&&fs::file_size(path)<=5*1024*1024)pixels=readFile(path);
 if(sha256(pixels)!=hash){auto reply=request("GET",joinUrl(base,std::string("/api/profile-media/")+kind),key,"","application/json",&accountMediaCancel,5*1024*1024,35000);pixels=reply.data;if(reply.code!=200||sha256(pixels)!=hash)throw std::runtime_error("사진이 변경되었습니다. 다시 불러오세요.");fs::create_directories(folder);atomicWrite(path,pixels);}result["files"][kind]=utf8(path.wstring());}
 }catch(const std::exception& e){result["error"]=userError(e.what());}target->event({"account_media","","",result});CoUninitialize();accountMediaActive=false;});}catch(...){accountMediaActive=false;accountMediaBusy=false;accountMediaMessage=L"사진 작업을 시작하지 못했습니다";}
}
void accountMediaReply(const Event& event){auto& row=event.data;if(str(row,"scope")!=store->workspaceScope||str(row,"owner")!=str(accountProfile,"account_id")||row.value("serial",uint64_t(0))!=accountMediaSerial)return;accountMediaBusy=false;accountMediaLoaded=true;
 auto applied=str(row,"applied_version");if(applied.size()==64){if(accountDraftVersion==str(row,"expected")){accountDraftVersion=applied;accountProfile["profile_version"]=applied;flushAccountDraft();}accountMediaRetry=json::object();}
 if(row.contains("error")){accountMediaMessage=wide(str(row,"error"));return;}
 accountMediaRows=row.at("metadata").at("media");accountMediaMessage=L"";for(auto& bitmap:accountMediaBitmaps)bitmap.Reset();accountMediaImages.reset();std::vector<fs::path> files;for(auto kind:{"avatar","banner"})if(row["files"].contains(kind))files.push_back(fs::path(wide(str(row["files"],kind))));if(files.size()==2)accountMediaImages.compare(files[0],files[1],accountMediaSerial);else if(files.size()==1)accountMediaImages.add(files[0],accountMediaSerial,true);InvalidateRect(hwnd,nullptr,FALSE);
}
void accountMediaTick(){if(accountMediaScope!=store->workspaceScope||accountMediaOwner!=str(accountProfile,"account_id")){if(!accountMediaScope.empty())resetAccountMedia();}if(page==13&&accountMediaSupported()&&!accountMediaLoaded&&!accountMediaBusy&&!accountMediaActive)startAccountMedia();for(auto& result:accountMediaImages.take()){if(result.revision!=accountMediaSerial||result.failed)continue;renderer.attach(hwnd);auto bitmap=renderer.pixels(result.width,result.height,result.pixels);auto name=utf8(result.path.filename().wstring());accountMediaBitmaps[name.rfind("avatar-",0)==0?0:1]=bitmap;InvalidateRect(hwnd,nullptr,FALSE);}}
void chooseAccountMedia(const std::string& kind){auto path=fileDialog(hwnd,false,L"사진\0*.png;*.jpg;*.jpeg;*.webp\0\0");if(path.empty())return;startAccountMedia({{"kind",kind},{"action","upload"},{"file",utf8(path)},{"token",id()}});}
void accountMediaMenu(const std::string& kind){HMENU menu=CreatePopupMenu();AppendMenuW(menu,MF_STRING,1,L"사진 선택");auto row=accountMediaRows.value(kind,json::object());AppendMenuW(menu,MF_STRING|(row.contains("current")&&!row["current"].is_null()?0:MF_GRAYED),2,L"사진 삭제");AppendMenuW(menu,MF_STRING|(flag(row,"can_undo")?0:MF_GRAYED),3,L"이전 사진 복원");POINT cursor;GetCursorPos(&cursor);auto command=TrackPopupMenu(menu,TPM_RETURNCMD|TPM_NONOTIFY,cursor.x,cursor.y,0,hwnd,nullptr);DestroyMenu(menu);if(command==1)chooseAccountMedia(kind);if(command==2||command==3)startAccountMedia({{"kind",kind},{"action",command==2?"clear":"undo"}});}
